mapper.select:
select id, father_recipe_id, recipe_id, weight_order, recipe_material_code, recipe_material_name, set_weight,
allow_error, remark, del_flag, create_by, create_time, update_by, update_time from t_mes_pmt_recipe_weight
where del_flag = '0' and father_recipe_id = #{fatherRecipeId,jdbcType=VARCHAR}
and INSTR(recipe_material_name, #{recipeMaterialName}) > 0
order by weight_order asc
order by ${orderStr}
